// Build a self-contained HTML page: one row per currency with a sparkline.
const { base, start_date, end_date, rates } = $input.first().json;
const days = Object.keys(rates).sort();
const currencies = Object.keys(rates[days[days.length - 1]]);

const sparkline = (values) => {
  const w = 160, h = 36, min = Math.min(...values), max = Math.max(...values);
  const pts = values.map((v, i) => {
    const x = (i / (values.length - 1)) * w;
    const y = max === min ? h / 2 : h - ((v - min) / (max - min)) * (h - 4) - 2;
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(' ');
  const up = values[values.length - 1] >= values[0];
  return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><polyline fill="none" stroke="${up ? '#16a34a' : '#dc2626'}" stroke-width="2" points="${pts}"/></svg>`;
};

const rows = currencies.map((c) => {
  const series = days.map((d) => rates[d][c]).filter((v) => v !== undefined);
  const first = series[0], last = series[series.length - 1];
  const change = ((last - first) / first) * 100;
  const color = change >= 0 ? '#16a34a' : '#dc2626';
  return `<tr><td class="cur">${c}</td><td class="num">${last.toFixed(4)}</td>` +
    `<td class="num" style="color:${color}">${change >= 0 ? '+' : ''}${change.toFixed(2)}%</td>` +
    `<td>${sparkline(series)}</td></tr>`;
}).join('\n');

const options = ['EUR', 'USD', 'GBP', 'JPY', 'CHF', 'CNY']
  .map((c) => `<a href="?base=${c}" class="${c === base ? 'active' : ''}">${c}</a>`).join(' ');

const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>FX Dashboard · ${base}</title>
<style>
  body { font: 15px/1.5 system-ui, sans-serif; margin: 0; padding: 24px; background: #f8fafc; color: #0f172a; }
  main { max-width: 640px; margin: auto; background: #fff; border-radius: 12px; padding: 24px; box-shadow: 0 1px 3px #0002; }
  h1 { font-size: 22px; margin: 0 0 4px; } .sub { color: #64748b; margin: 0 0 16px; }
  table { width: 100%; border-collapse: collapse; } td, th { padding: 8px; border-bottom: 1px solid #e2e8f0; text-align: left; }
  .num { text-align: right; font-variant-numeric: tabular-nums; } .cur { font-weight: 600; }
  nav a { padding: 2px 8px; border-radius: 6px; text-decoration: none; color: #2563eb; } nav a.active { background: #2563eb; color: #fff; }
  footer { color: #94a3b8; font-size: 12px; margin-top: 16px; }
</style></head>
<body><main>
<h1>1 ${base} =</h1>
<p class="sub">ECB reference rates · ${start_date} → ${end_date}</p>
<nav>Base: ${options}</nav>
<table><thead><tr><th>Currency</th><th class="num">Rate</th><th class="num">30 days</th><th>Trend</th></tr></thead>
<tbody>
${rows}
</tbody></table>
<footer>Served by n8n · Recipe 17 of the n8n Cookbook · Data: frankfurter.dev</footer>
</main></body></html>`;

return [{ json: { html } }];
